import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isWarping, setIsWarping] = useState(false);

  useEffect(() => {
    const warpTimer = setTimeout(() => setIsWarping(true), 3200);
    const completeTimer = setTimeout(onComplete, 4200);
    return () => { 
      clearTimeout(warpTimer); 
      clearTimeout(completeTimer); 
    };
  }, [onComplete]);

  // The secret "Apple" Bezier Curve for motion
  const appleEase = [0.16, 1, 0.3, 1];

  return (
    <div className="h-screen w-full bg-[#FFF24D] flex items-center justify-center relative overflow-hidden">

      {/* 1. SOFT AMBIENT DEPTH (The Swiggy Look) */}
      <div className="absolute inset-0 bg-glow" />

      {/* 2. THE MAIN UNIT (Stays Clean and Solid) */}
      <motion.div 
        animate={isWarping ? { scale: 12, opacity: 0, filter: "blur(50px)" } : { scale: 1 }}
        transition={{ duration: 1, ease: appleEase }}
        className="flex flex-col items-center"
      >
        <div className="flex items-center justify-center animate-expand">

          {/* THE LOGO: Beet Red with a Soft Lenin Blue Shadow */}
          <motion.h1 
            initial={{ y: 100, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ duration: 1.5, ease: appleEase }}
            className="text-[12rem] md:text-[20rem] font-[1000] italic text-[#AB1717] leading-none select-none tracking-tighter drop-shadow-[0_15px_30px_rgba(0,51,102,0.15)]"
          >
            T2T
          </motion.h1>
        </div>

        {/* THE SUBTITLE: Grassy Green (Rising from beneath) */}
        <motion.div 
          initial={{ y: 40, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ delay: 0.8, duration: 1.2, ease: appleEase }}
          className="mt-[-20px] md:mt-[-40px]"
        >
          <span className="text-[#47510B] font-black text-3xl md:text-5xl uppercase italic tracking-[0.8em] pl-[0.8em]">
            Worker
          </span>
        </motion.div>
      </motion.div>

      {/* 3. MINIMALIST PROGRESS (Lenin Blue - Clean & Thin) */}
      <div className="absolute bottom-16 w-32 h-[1px] bg-[#003366]/10 overflow-hidden">
        <motion.div 
          initial={{ x: "-100%" }}
          animate={{ x: "100%" }}
          transition={{ duration: 3, ease: "easeInOut", repeat: Infinity }}
          className="h-full w-1/2 bg-[#003366]"
        />
      </div>

      {/* 4. PERIMETER BRANDING (The Professional Touch) */}
      <div className="absolute bottom-8 w-full px-12 flex justify-between text-[10px] font-black text-[#003366] opacity-30 uppercase tracking-widest">
        <span>Trash2Track_System</span>
        <span>v.4.02</span>
      </div>
    </div>
  );
};

export default WorkerSplash;
